values ('aaaa0006-0000-4000-8000-000000000005', 'en', null, 'German B2 — Upper Intermediate', 'An upper-intermediate German course for learners who can already hold their own: follow the news, argue a position with nuance, switch register, and command complex structures like the passive, reported speech, and advanced connectors. Aligned to CEFR B2; structure adapted from open German curricula on OER Commons (CC BY 4.0).', 'B2', 'fluency', 13, true, 'language', '{aaaa0006-0000-4000-8000-000000000003}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0006-0000-4000-8000-000000000005', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Media & current affairs', 'vocab', '{"items":[{"term":"die Schlagzeile","translation":"the headline","ipa":"diː ˈʃlaːkˌtsaɪlə","example":"Die Schlagzeile war reißerisch, doch der Artikel selbst blieb sachlich."},{"term":"die Berichterstattung","translation":"the reporting / coverage","ipa":"diː bəˈʁɪçtɛɐ̯ˌʃtatʊŋ","example":"Die Berichterstattung über den Prozess war erstaunlich einseitig."},{"term":"glaubwürdig","translation":"credible / trustworthy","ipa":"ˈɡlaʊpˌvʏʁdɪç","example":"Ich teile eine Nachricht erst, wenn die Quelle glaubwürdig ist."},{"term":"etwas in Frage stellen","translation":"to call something into question","ipa":"ˈɛtvas ɪn ˈfʁaːɡə ˈʃtɛlən","example":"Fachleute stellen die offiziellen Zahlen in Frage."},{"term":"die öffentliche Meinung","translation":"public opinion","ipa":"diː ˈœfn̩tlɪçə ˈmaɪnʊŋ","example":"Soziale Medien beeinflussen die öffentliche Meinung immer stärker."},{"term":"voreingenommen","translation":"biased / prejudiced","ipa":"ˈfoːɐ̯ʔaɪnɡəˌnɔmən","example":"Der Kommentar wirkt voreingenommen zugunsten der Regierung."}]}'::jsonb, 'Many of these nouns are compounds — die Nachricht + der Sprecher = der Nachrichtensprecher. The last element decides the gender and takes the plural ending, so learning the final noun tells you how to inflect the whole word.', 9),
  (2, 'Environment & society', 'vocab', '{"items":[{"term":"die Nachhaltigkeit","translation":"sustainability","ipa":"diː ˈnaːxˌhaltɪçkaɪt","example":"Nachhaltigkeit darf kein bloßes Werbeversprechen bleiben."},{"term":"der Klimawandel","translation":"climate change","ipa":"deːɐ̯ ˈkliːmaˌvandl̩","example":"Der Klimawandel betrifft längst auch unsere Region."},{"term":"die Ressourcen schonen","translation":"to conserve resources","ipa":"diː ʁɛˈsʊʁsn̩ ˈʃoːnən","example":"Wer Ressourcen schont, spart langfristig auch Geld."},{"term":"die soziale Gerechtigkeit","translation":"social justice","ipa":"diː zoˈtsi̯aːlə ɡəˈʁɛçtɪçkaɪt","example":"Ohne soziale Gerechtigkeit gerät der Zusammenhalt in Gefahr."},{"term":"sich engagieren","translation":"to get involved / commit oneself","ipa":"zɪç ɛŋɡaˈʒiːʁən","example":"Immer mehr Jugendliche engagieren sich für den Umweltschutz."},{"term":"die Auswirkung","translation":"the effect / impact","ipa":"diː ˈaʊsˌvɪʁkʊŋ","example":"Die Auswirkungen dieser Entscheidung zeigen sich erst in Jahren."}]}'::jsonb, 'Abstract topics love nominalisation: nachhaltig (adjective) → die Nachhaltigkeit (noun). The suffix -keit turns an adjective into a feminine noun, a pattern you will meet constantly at B2.', 9),
  (3, 'The Passiv: the passive voice', 'grammar', '{"sections":[{"heading":"Why and when the passive is used","text":"The Passiv shifts the focus away from who does something and onto what happens. It is everywhere in news, reports and instructions, where the actor is unknown or simply irrelevant: Das Gesetz wird heute verabschiedet (The law is being passed today). Compare the active Der Bundestag verabschiedet das Gesetz — the passive lets you drop the doer entirely."},{"heading":"Forming the Vorgangspassiv","text":"The process passive is built with werden plus the past participle at the end of the clause: Der Bericht wird geschrieben (is being written), Der Bericht wurde geschrieben (was written), Der Bericht ist geschrieben worden (has been written). Note that in the perfect, the participle of werden appears as worden, never geworden."},{"heading":"Naming the agent with von and durch","text":"When you do want to mention who or what is responsible, use von for a person or institution and durch for a means or cause: Das Projekt wurde von der Kommission genehmigt (by the commission); Die Stadt wurde durch das Hochwasser zerstört (by the flood). Often, though, the whole point of the passive is to leave the agent unsaid."},{"heading":"Modal verbs and the Zustandspassiv","text":"A modal verb combines neatly with the passive infinitive werden: Das Formular muss unterschrieben werden (must be signed). Do not confuse this with the state passive (Zustandspassiv), which uses sein and describes a finished result: Die Tür ist geschlossen (the door is closed) versus Die Tür wird geschlossen (the door is being closed)."}]}'::jsonb, null, 13),
  (4, 'Relativsätze & advanced connectors', 'grammar', '{"sections":[{"heading":"Relative clauses and their case","text":"A relative clause adds information about a noun and sends its verb to the end. The relative pronoun matches the noun in gender and number, but takes its case from its own role in the clause: Der Kollege, der neben mir sitzt (nominative — he sits); Der Kollege, den ich gestern traf (accusative — I met him); Der Kollege, dem ich half (dative — I helped him)."},{"heading":"Genitive and prepositional relatives","text":"The genitive relative pronouns dessen (masculine/neuter) and deren (feminine/plural) mean ''whose'': Die Autorin, deren Buch gerade erschien, hält morgen einen Vortrag. When a preposition is involved, it stands in front of the pronoun and fixes the case: Das Thema, über das wir sprechen; Die Firma, bei der sie arbeitet."},{"heading":"Two-part connectors","text":"B2 speech is knitted together with correlative pairs. Zwar …, aber concedes then counters: Der Plan ist zwar teuer, aber wirkungsvoll. Je …, desto links two comparatives and demands verb-final then verb-second: Je mehr wir üben, desto sicherer werden wir. And entweder … oder, weder … noch, sowohl … als auch let you balance alternatives precisely."},{"heading":"Connectors that reorder the sentence","text":"Adverbial connectors like trotzdem (nevertheless), deshalb (therefore), dennoch (yet) and außerdem (moreover) count as the first element, so the verb still comes second — and the subject follows it: Es regnete; trotzdem gingen wir spazieren. Contrast this with subordinating obwohl, which pushes the verb to the very end: Wir gingen spazieren, obwohl es regnete."}]}'::jsonb, null, 14),
  (5, 'Konjunktiv I: reported speech', 'grammar', '{"sections":[{"heading":"What the Konjunktiv I signals","text":"In careful writing and journalism, Germans mark reported speech with the Konjunktiv I to show they are relaying someone''s words without vouching for them: Der Minister sagte, er sei zuversichtlich (The minister said he was confident). That sei quietly says ''these are his words, not necessarily the facts.''"},{"heading":"Forming Konjunktiv I","text":"Take the infinitive stem and add the endings -e, -est, -e, -en, -et, -en: kommen → er komme, machen → sie mache. The verb sein is irregular and by far the most common: ich sei, du seist, er sei, wir seien, sie seien. Because it often looks identical to the ordinary present, the third person singular is where the Konjunktiv I is clearest."},{"heading":"Switching to Konjunktiv II when forms clash","text":"When the Konjunktiv I form looks exactly like the indicative — as it does for most plural forms — German swaps in the Konjunktiv II to keep the meaning transparent: Sie sagten, sie hätten keine Zeit (not the ambiguous haben). So haben → hätten, können → könnten, werden → würden step in wherever Konjunktiv I would be invisible."},{"heading":"Tense in reported speech","text":"Konjunktiv I distinguishes only three time frames. Present reports use the plain form (er sei, er komme); anything past collapses into one perfect form (er sei gekommen, er habe gearbeitet); the future uses werde (er werde kommen). Notice there is no separate past tense — Er sagte, er habe das Dokument gelesen covers ''he read'' and ''he has read'' alike."}]}'::jsonb, null, 13),
  (6, 'Work & negotiation', 'vocab', '{"items":[{"term":"der Kompromiss","translation":"the compromise","ipa":"deːɐ̯ ˌkɔmpʁoˈmɪs","example":"Am Ende fanden beide Seiten einen tragfähigen Kompromiss."},{"term":"die Gehaltsverhandlung","translation":"the salary negotiation","ipa":"diː ɡəˈhaltsfɛɐ̯ˌhandlʊŋ","example":"Vor der Gehaltsverhandlung sammle ich Argumente und Marktdaten."},{"term":"entgegenkommen","translation":"to accommodate / meet halfway","ipa":"ɛntˈɡeːɡn̩ˌkɔmən","example":"Beim Termin kann ich Ihnen gern entgegenkommen."},{"term":"die Rahmenbedingungen","translation":"the general terms / framework conditions","ipa":"diː ˈʁaːmənbəˌdɪŋʊŋən","example":"Bevor wir zusagen, klären wir die Rahmenbedingungen."},{"term":"auf etwas bestehen","translation":"to insist on something","ipa":"aʊf ˈɛtvas bəˈʃteːən","example":"Ich bestehe auf einer schriftlichen Zusage."},{"term":"in Aussicht stellen","translation":"to hold out the prospect of","ipa":"ɪn ˈaʊszɪçt ˈʃtɛlən","example":"Die Leitung stellte eine Beförderung im nächsten Jahr in Aussicht."}]}'::jsonb, 'Negotiation language leans on the Konjunktiv II to stay polite: könnten, würden and hätten gern soften a demand into a proposal. Keep these forms close when the register needs to be diplomatic.', 9),
  (7, 'Debate: disagreeing politely', 'roleplay', '{"scenario":"A moderated panel discussion on whether the working week should be shortened to four days. You argue in favour. Open with a clear thesis, back it with two arguments and an example each, then push back on a strong objection about productivity without dismissing it. Use disagreement softeners like Das sehe ich anders, Da muss ich Ihnen widersprechen, and Ich verstehe Ihren Punkt, aber… and weave in the connectors zwar … aber and je … desto.","persona":"A sharp but fair moderator who plays devil''s advocate, cites studies against your position, interrupts to demand evidence, and rewards you for conceding a nuance while holding your line","goal":"Sustain an abstract argument over several turns, disagreeing respectfully in the Sie register while defending a thesis with structured reasoning"}'::jsonb, null, 12),
  (8, 'A workplace meeting', 'roleplay', '{"scenario":"A project status meeting at a company in Frankfurt. A deadline is slipping and you must propose a way forward. Summarise where the project stands, name the problem plainly, suggest two concrete options, invite objections, and steer the group toward a decision with next steps and owners. Use meeting phrases like Lassen Sie mich kurz zusammenfassen, Ich möchte vorschlagen, dass…, Wie sehen Sie das? and Halten wir also fest, dass…","persona":"A results-oriented team lead who uses Sie, keeps interrupting to ask for timelines and responsibilities, resists vague answers, and expects every point to end in a concrete action","goal":"Move a stalled project forward by presenting options, managing disagreement, and closing with an agreed plan and clear responsibilities — entirely in German"}'::jsonb, null, 11),
  (9, 'Reading: opinion — should cities go car-free?', 'reading', '{"sections":[{"heading":"The article","text":"Read this opinion piece: ''Immer mehr europäische Städte sperren ihre Innenstädte für Autos — und die Debatte darüber wird hitzig geführt. Befürworter argumentieren, dass autofreie Zentren die Luft verbessern, den Lärm verringern und den öffentlichen Raum den Menschen zurückgeben. Kritiker hingegen warnen, der Einzelhandel werde leiden und Menschen mit eingeschränkter Mobilität würden ausgeschlossen. Fest steht: Eine Verkehrswende gelingt nur dann, wenn gleichzeitig in einen zuverlässigen Nahverkehr investiert wird. Wer Autos verbannt, ohne Alternativen zu schaffen, verlagert das Problem lediglich an den Stadtrand.''"},{"heading":"Following the argument","text":"Notice how the writer signals structure. Befürworter argumentieren, dass… introduces one side; Kritiker hingegen warnen… pivots to the other, with hingegen marking the contrast. The passive wird … geführt and werde leiden keeps the focus on the debate itself rather than on named people, a hallmark of opinion journalism."},{"heading":"Reading between the lines","text":"The author is not neutral. The phrase Fest steht (one thing is certain) introduces the writer''s own thesis: a transport shift only works if reliable public transport is funded at the same time. The closing image — verlagert das Problem lediglich an den Stadtrand (merely shifts the problem to the edge of the city) — is a warning, not a description, and tells you where the writer stands."},{"heading":"Your turn","text":"Write a short reaction of four or five sentences. State whether you agree, give one reason using weil or da, raise one counterargument with zwar … aber, and close with your own position introduced by Meiner Meinung nach… Try to use one passive construction, just as the article does."}]}'::jsonb, null, 13),
  (10, 'B2 checkpoint', 'quiz', '{"questions":[{"prompt":"Choose the correct process passive: ''The report is being written.''","options":["Der Bericht ist geschrieben.","Der Bericht wird geschrieben.","Der Bericht hat geschrieben.","Der Bericht wurde geschrieben worden."],"answer":1,"explanation":"The Vorgangspassiv uses werden plus the participle: Der Bericht wird geschrieben. sein + participle (ist geschrieben) is the state passive and describes a finished result."},{"prompt":"Complete the perfect passive: ''Das Gesetz ist gestern verabschiedet ___.''","options":["geworden","worden","gewesen","werden"],"answer":1,"explanation":"In the perfect passive the participle of werden appears as worden, never geworden: ist verabschiedet worden."},{"prompt":"Pick the right relative pronoun: ''Die Kollegin, ___ Projekt gewann, ist im Urlaub.''","options":["die","deren","dessen","der"],"answer":1,"explanation":"''Whose'' before a feminine antecedent is the genitive deren: die Kollegin, deren Projekt… dessen is masculine/neuter."},{"prompt":"Which sentence uses je … desto correctly?","options":["Je mehr wir üben, desto werden wir sicherer.","Je mehr wir üben, desto sicherer werden wir.","Je mehr üben wir, desto sicherer wir werden.","Desto mehr wir üben, je sicherer werden wir."],"answer":1,"explanation":"After je the verb goes to the end (je mehr wir üben), and after desto the clause is verb-second with the comparative first: desto sicherer werden wir."},{"prompt":"Report this in Konjunktiv I: ''Er sagte, er ___ zuversichtlich.''","options":["ist","sei","wäre","war"],"answer":1,"explanation":"Reported speech uses the Konjunktiv I of sein in the third person singular: er sei. wäre is Konjunktiv II, used only when Konjunktiv I would clash with the indicative."},{"prompt":"Which connector keeps the verb in second position?","options":["obwohl","weil","trotzdem","dass"],"answer":2,"explanation":"trotzdem is an adverbial connector that counts as the first element, so the verb stays second: Es regnete; trotzdem gingen wir. obwohl, weil and dass are subordinating and send the verb to the end."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0006-0000-4000-8000-000000000005' and l.position = v.pos
